    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/LabeledLinkExample_zZc> ;
            sh:resultMessage "value must be a resolvable URL, but we aren't testing to see if the URL resolves..... Can't get xsd:anyURI to work with JSON Schema validation..." ;
            sh:resultPath schema1:url ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:PatternConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "value must be a resolvable URL, but we aren't testing to see if the URL resolves..... Can't get xsd:anyURI to work with JSON Schema validation..." ;
                    sh:minCount 1 ;
                    sh:path schema1:url ;
                    sh:pattern "^https?:\\/\\/[^\\s]+$" ] ;
            sh:value "" ] .

